import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from 'react-router-dom';
import "./RiverDashboard.css"; // Reusing your existing styles

// Smart API Logic
const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

const FloodMap = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [floodData, setFloodData] = useState(null);

  useEffect(() => {
    const fetchFloodAnalysis = async () => {
      try {
        // Calls the view you already created in views.py
        const response = await axios.get(`${API_BASE_URL}/api/weather/flood-analysis`);
        if (response.data) {
          setFloodData(response.data);
        }
      } catch (error) {
        console.error("Analysis Failed:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchFloodAnalysis();
  }, []);

  if (loading) return <div className="rd-loading"><div className="rd-spinner"></div><p>Analyzing Terrain (DEM)...</p></div>;

  return (
    <div className="rd-container">
      <nav className="rd-nav-overlay">
        <div className="rd-wrapper rd-flex-between">
            <div className="rd-brand"><i className="fas fa-water"></i> Periyar<span>Watch</span></div>
            <button onClick={() => navigate('/river-forecast')} style={{background:'transparent', border:'1px solid white', color:'white', padding:'5px 15px', borderRadius:'5px', cursor:'pointer'}}>
              <i className="fas fa-arrow-left"></i> Back to Dashboard
            </button>
        </div>
      </nav>

      <main className="rd-main-content rd-wrapper" style={{marginTop: '100px'}}>
        
        <div className="rd-hero-text" style={{textAlign: 'center', marginBottom: '40px'}}>
          <h1><i className="fas fa-search-location"></i> Flood Impact Analysis</h1>
          <p>AI-driven analysis using Satellite Elevation Data (DEM)</p>
        </div>

        {/* SUMMARY CARDS */}
        <div className="rd-stats-grid">
            <div className="rd-card glass">
                <div className="card-head"><span>Water Level</span></div>
                <div className="big-stat">{floodData?.current_water_level} m</div>
            </div>
            <div className="rd-card glass">
                <div className="card-head"><span>Affected Locations</span></div>
                <div className="big-stat" style={{color: '#ef4444'}}>{floodData?.flooded_count || 0}</div>
            </div>
            <div className="rd-card glass">
                <div className="card-head"><span>Status</span></div>
                <div className="big-stat" style={{color: floodData?.status === 'alert' ? '#ef4444' : '#10b981'}}>
                    {floodData?.status === 'alert' ? "CRITICAL" : "SAFE"}
                </div>
            </div>
        </div>

        {/* DETAILED TABLE */}
        {floodData?.data && floodData.data.length > 0 ? (
          <section className="rd-section glass" style={{marginTop: '30px'}}>
            <div className="sec-header"><h3>Identified Flood Zones (Kalady Region)</h3></div>
            <div style={{overflowX: 'auto'}}>
              <table style={{width: '100%', borderCollapse: 'collapse', color: 'white', marginTop: '15px'}}>
                <thead>
                  <tr style={{borderBottom: '1px solid rgba(255,255,255,0.2)', textAlign: 'left'}}>
                    <th style={{padding: '12px'}}>Coordinates (Lat, Lon)</th>
                    <th style={{padding: '12px'}}>Flood Depth</th>
                    <th style={{padding: '12px'}}>AI Explanation</th>
                  </tr>
                </thead>
                <tbody>
                  {floodData.data.slice(0, 50).map((row, idx) => ( // Showing top 50 points
                    <tr key={idx} style={{borderBottom: '1px solid rgba(255,255,255,0.05)'}}>
                      <td style={{padding: '12px', fontFamily: 'monospace', color:'#fbbf24'}}>
                        {row.lat}, {row.lon}
                      </td>
                      <td style={{padding: '12px', fontWeight:'bold'}}>
                        +{row.depth} m
                      </td>
                      <td style={{padding: '12px'}}>{row.explanation}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        ) : (
          <div className="rd-section glass" style={{marginTop: '30px', textAlign:'center', padding:'40px'}}>
            <h3>No flood risks detected at current water levels.</h3>
            <p>The river is flowing within safe banks.</p>
          </div>
        )}

      </main>
    </div>
  );
};

export default FloodMap;
